def most_common_word(text):
    def count(words, seen):
        if not words:
            return seen
        seen[words[0]] = seen.get(words[0], 0) + 1
        return count(words[1:], seen)
    tally = count(text.lower().split(), {})
    return sorted(tally, key=tally.get)[-1]

import re
from collections import defaultdict

def most_common_word(text):
    found = defaultdict(int)
    for match in re.findall(r"[a-z']+", text.lower()):
        found[match] += 1
    return max(found, key=found.get)

def most_common_word(text):
    words = text.lower().split()
    return max(set(words), key=words.count)

def most_common_word(text):
    words = text.lower().split()
    i = 0
    best = None
    best_n = 0
    while i < len(words):
        n = 0
        for other in words:
            if other == words[i]:
                n += 1
        if n > best_n:
            best, best_n = words[i], n
        i += 1
    return best

def top_word(sentence):
    freq = {}
    for w in sentence.lower().split():
        if w in freq:
            freq[w] += 1
        else:
            freq[w] = 1
    winner = ""
    highest = 0
    for w, n in freq.items():
        if n > highest:
            winner = w
            highest = n
    return winner

