def frequent_word(s):
    # tally the words

    tally = {}
    for token in s.lower().split():   # one word at a time
        if token in tally:
            tally[token] += 1
        else:
            tally[token] = 1

    leader = ""      # best word so far
    leader_total = 0
    for token, total in tally.items():
        if total > leader_total:
            leader = token
            leader_total = total
    return leader   # done
